const ROOM_NAMES=['밀물의 잔교','밧줄꾼의 망루','푸른 현상 동굴','등불 아래의 결투','밀수꾼의 숨은 길','소금 묻은 계단','버려진 닻의 정박지','갈매기의 지붕길','술통이 구르는 부두','밤바람의 사다리','울음 없는 만조','떠돌이의 낡은 갑판'];
let eid=0;function spawnEnemy(type,x,y){const stats={sailor:[68,13,90],crab:[46,10,125],rope:[58,11,75],elite:[200,19,95],boss:[880,22,120]}[type];let e={id:++eid,type,x,y,vx:0,vy:0,w:type==='boss'?64:type==='crab'?48:38,h:type==='crab'?32:type==='boss'?112:77,hp:stats[0],maxHp:stats[0],damage:stats[1],speed:stats[2],face:-1,state:'idle',timer:rand(.5,1.3),windup:0,attack:0,cooldown:rand(.6,1.8),stun:0,hurt:0,poison:0,poisonTick:0,ground:false,walk:rand(0,6),taunt:'',tauntTime:0,phase:1,pattern:0,hit:false,dead:0};G.enemies.push(e);return e;}
function has(id){return G.run?.boons.includes(id);}
function addLaugh(n){if(G.run)G.run.laugh=clamp(G.run.laugh+n,0,100);}
function toast(s,time=3){$('#toast').textContent=s;$('#toast').classList.add('visible');G.toastTime=time;}
function audioStart(){if(!meta.sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();}catch(e){}}
function tone(freq,dur=.15,type='sine',vol=.06,slide=1){if(!meta.sound||!audioCtx)return;let o=audioCtx.createOscillator(),v=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,freq*slide),audioCtx.currentTime+dur);v.gain.setValueAtTime(vol,audioCtx.currentTime);v.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(v);v.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur);}
function noise(dur=.09,vol=.08){if(!meta.sound||!audioCtx)return;let b=audioCtx.createBuffer(1,audioCtx.sampleRate*dur,audioCtx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*(1-i/a.length);let s=audioCtx.createBufferSource(),v=audioCtx.createGain();s.buffer=b;v.gain.value=vol;s.connect(v);v.connect(audioCtx.destination);s.start();}
function sfx(type){if(type==='slash'){noise(.1,.07);tone(350,.1,'triangle',.025,.25);}if(type==='hit'){noise(.07,.14);tone(100,.13,'triangle',.08,.4);}if(type==='parry'){[587,880,1174].forEach((f,i)=>tone(f,.3+i*.07,'sine',.045));noise(.055,.05);}if(type==='jump')tone(180,.15,'sine',.035,2);if(type==='dash')noise(.2,.055);if(type==='coin'){tone(988,.1,'sine',.035);tone(1318,.2,'sine',.02);}if(type==='chicken'){tone(390,.16,'square',.022,.7);tone(570,.22,'triangle',.035,.3);}if(type==='bomb'){noise(.3,.13);tone(70,.35,'triangle',.1,.3);}if(type==='ult'){[196,294,392,587].forEach(f=>tone(f,.8,'triangle',.035));}if(type==='hurt'){noise(.13,.07);tone(160,.2,'sawtooth',.025,.3);}}
function music(dt){if(!meta.sound||!audioCtx||G.mode==='paused')return;musicClock-=dt;if(musicClock>0)return;musicClock=.33;let melody=[196,0,294,247,220,0,330,294,196,247,294,392,330,294,247,0],f=melody[musicTick%16];if(f)tone(f,.42,'triangle',.012);if(musicTick%4===0)tone([98,110,82.41,73.42][Math.floor(musicTick/4)%4],.8,'sine',.035);if(G.mode==='play'&&musicTick%2===0)noise(.035,.014);musicTick++;}
function pollPad(){let pads=navigator.getGamepads?.()||[],pad=Array.from(pads).find(Boolean);if(!pad){lastPad={};return;}let map={left:(pad.axes[0]||0)<-.25,right:(pad.axes[0]||0)>.25,up:pad.axes[1]<-.4,down:pad.axes[1]>.4,jump:pad.buttons[0]?.pressed,attack:pad.buttons[2]?.pressed,dash:pad.buttons[1]?.pressed,parry:pad.buttons[5]?.pressed,skillU:pad.buttons[6]?.pressed,skillI:pad.buttons[7]?.pressed,ult:pad.buttons[3]?.pressed,interact:pad.buttons[4]?.pressed,pause:pad.buttons[9]?.pressed};for(let [key,v] of Object.entries(map)){if(v){inputDevice='gamepad';keys.add('pad:'+key);if(!lastPad[key])pressed.add(key);}else keys.delete('pad:'+key);}lastPad=map;}
const KEYMAP={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',Space:'jump',KeyJ:'attack',KeyK:'dash',KeyL:'parry',KeyU:'skillU',KeyI:'skillI',KeyO:'ult',KeyE:'interact',Escape:'pause'};
function down(action){return keys.has('pad:'+action)||Object.entries(KEYMAP).some(([code,a])=>a===action&&keys.has(code));}
function tap(action){return pressed.has(action);}
window.addEventListener('keydown',e=>{if(!['play','hub'].includes(G.mode)&&e.code!=='Escape'){if(G.mode==='title'&&e.code==='Enter'&&e.target.tagName!=='BUTTON'){audioStart();hub();}return;}let a=KEYMAP[e.code];if(a){e.preventDefault();inputDevice='keyboard';if(!e.repeat)pressed.add(a);keys.add(e.code);}if(e.code==='Enter'&&G.mode==='title'){audioStart();hub();}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();pressed.clear();if(['play','hub'].includes(G.mode))pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&['play','hub'].includes(G.mode))pause();});
function particle(x,y,color,n=12,speed=140,size=3,gravity=350){for(let i=0;i<n;i++){let a=rand(-Math.PI,Math.PI),v=rand(speed*.25,speed);G.particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,color,size:rand(size*.5,size*1.5),life:rand(.25,.7),max:.7,g:gravity});}if(G.particles.length>500)G.particles.splice(0,G.particles.length-500);}
function textAt(text,x,y,color='#ffdb94',size=19){G.texts.push({text,x,y,vy:-35,time:1,max:1,color,size});}
function shake(amount=7){if(!meta.reduced)G.shake=Math.max(G.shake,amount);}
function damageEnemy(e,damage,knock=100,parried=false){if(e.hp<=0)return;e.hp-=damage;e.hurt=.16;e.vx=G.p.face*knock;if(e.type!=='boss'){if(parried||!['windup','attack'].includes(e.state))e.stun=Math.max(e.stun,parried?1.3:.10);e.vy=-60;}else if(parried)e.stun=1.1;if(has('poison')&&!parried)e.poison=3;particle(e.x,e.y-e.h*.5,parried?'#c6fcf6':'#ffd69c',parried?27:12,parried?360:200,3);textAt(Math.round(damage),e.x+rand(-12,12),e.y-e.h-5,parried?'#b4fff0':'#ffddb3',parried?28:18);G.hitstop=parried?.085:.045;shake(parried?11:4);sfx(parried?'parry':'hit');if(e.hp<=0)killEnemy(e);}
function killEnemy(e){e.hp=0;e.dead=.65;e.state='dead';G.run.kills++;addLaugh(6);for(let i=0;i<(e.type==='boss'?18:e.type==='elite'?8:3);i++)G.drops.push({x:e.x,y:e.y-30,vx:rand(-180,180),vy:rand(-340,-140),type:'coin',t:0});if(Math.random()<.25||e.type==='boss'||e.type==='elite'){meta.film+=e.type==='boss'?3:1;G.run.filmGained+=e.type==='boss'?3:1;textAt('필름 +'+(e.type==='boss'?3:1),e.x,e.y-e.h-45,'#a0dbef',16);}if(e.type==='elite'||e.type==='boss'){let n=e.type==='boss'?5:2;meta.teeth+=n;G.run.teethGained+=n;textAt('금니 +'+n,e.x,e.y-e.h-75,'#f5cd78',20);}save();if(e.type==='boss'){G.clearTimer=2.7;G.cleared=true;G.flash=.4;G.banner={title:'허풍도 끝이 나는 법.',sub:'깡패 선장 브락 · 격파',time:3};sfx('ult');}}
function hurtPlayer(damage,source){let p=G.p;if(p.invul>0||p.dash>0||G.mode!=='play')return;if(p.parry>0&&source){parrySuccess(source);return;}G.run.hp=Math.max(0,G.run.hp-damage);p.hurt=.32;p.invul=.85;p.vx=(source&&source.x<p.x?1:-1)*300;p.vy=-160;addLaugh(-12);shake(11);G.flash=.15;G.hitstop=.06;particle(p.x,p.y-40,'#e59186',14,180);textAt('-'+damage,p.x,p.y-90,'#ff9c93',23);sfx('hurt');if(G.run.hp<=0){if(has('secondlife')&&!G.run.revived){G.run.revived=true;G.run.hp=Math.ceil(G.run.maxHp*.35);p.invul=2;toast('로사의 외상: “아직 계산 안 했잖아!”');particle(p.x,p.y-40,'#96f0c0',40,270);sfx('parry');}else die();}}
function parrySuccess(e){G.p.parry=0;G.p.invul=.45;e.attack=0;e.windup=0;e.state='stun';e.stun=has('stunparry')?2.3:1.3;e.cooldown=1.1;let damage=(G.run.weapon==='sword'?38:30)+(has('stunparry')?12:0);damageEnemy(e,damage,420,true);G.run.parries++;addLaugh(24);if(has('healparry'))G.run.hp=Math.min(G.run.maxHp,G.run.hp+5);G.slashes.push({x:G.p.x+G.p.face*50,y:G.p.y-45,face:G.p.face,combo:2,time:.32,max:.32,parry:true});textAt(pick(['입만 일등 항해사!','거울부터 보고 와!','네 허풍은 만선이네!']),G.p.x,G.p.y-125,'#bbfff0',21);}
function doAttack(){let p=G.p;if(p.attackCD>0||p.dash>0||p.hurt>0)return;if(p.comboTimer<=0)p.combo=0;else p.combo=(p.combo+1)%3;p.comboTimer=.82;let flail=G.run?.weapon==='flail';p.attack=flail?.4:.28;p.attackCD=flail?.39:.25;p.hitIds.clear();let reach=flail?170:p.combo===2?147:112;G.slashes.push({x:p.x+p.face*48,y:p.y-42,face:p.face,combo:p.combo,time:flail?.35:.24,max:flail?.35:.24,flail});p.vx=p.face*(p.combo===2?220:105);sfx('slash');if(G.mode==='play'){for(let e of G.enemies){if(e.hp<=0)continue;let dx=(e.x-p.x)*p.face,dy=Math.abs((e.y-e.h*.45)-(p.y-40));if(dx>-22&&dx<reach+e.w*.5&&dy<80){let damage=(flail?[21,25,38]:[17,20,30])[p.combo];damageEnemy(e,damage,p.combo===2?320:130);p.hitIds.add(e.id);addLaugh(flail?7:4);if(has('slip')&&p.combo===2){e.stun=Math.max(e.stun,1.4);e.vx=p.face*500;}}}}}
function useSkill(which){let p=G.p;if(G.mode!=='play')return;if(which==='U'&&p.skillU<=0){p.skillU=has('chicken')?4:6;for(let e of G.enemies)if(e.hp>0&&Math.abs(e.x-p.x)<220&&Math.abs(e.y-p.y)<140){damageEnemy(e,has('chicken')?34:18,380);e.stun=Math.max(e.stun,.75);}addLaugh(14);G.slashes.push({x:p.x,y:p.y-45,time:.5,max:.5,chicken:true,face:p.face});particle(p.x,p.y-40,'#f0cf67',30,350,5);textAt('꽥! 말이 너무 많아!',p.x,p.y-100,'#ffe9a9',19);sfx('chicken');}if(which==='I'&&p.skillI<=0){p.skillI=8;G.projectiles.push({x:p.x+p.face*25,y:p.y-57,vx:p.face*520,vy:-390,type:'bomb',time:1.2,owner:'hero'});sfx('slash');}}
function ultimate(){if(G.mode!=='play'||G.run.laugh<100)return;G.run.laugh=0;G.p.invul=1.4;let damage=72+(has('radiance')?40:0);for(let e of G.enemies)if(e.hp>0&&Math.abs(e.x-G.p.x)<1200){damageEnemy(e,damage,500,true);e.stun=Math.max(e.stun,2);}G.flash=.7;shake(20);G.hitstop=.12;particle(G.p.x,G.p.y-45,'#ffd991',85,850,6,0);G.banner={title:'네 허풍에 돛을 달면 세계 일주도 하겠어!',sub:'필살 대사 · 관중 대폭소',time:2.5};sfx('ult');}
function physics(a,dt){const oldY=a.y;a.vy+=1650*dt;a.x+=a.vx*dt;a.y+=a.vy*dt;a.ground=false;if(a.vy>=0){for(let p of G.platforms){if(a.x+a.w*.4>p.x&&a.x-a.w*.4<p.x+p.w&&oldY<=p.y+8&&a.y>=p.y){a.y=p.y;a.vy=0;a.ground=true;break;}}}a.x=clamp(a.x,25,G.world-25);}
function updatePlayer(dt){let p=G.p;for(let k of ['attack','attackCD','comboTimer','dashCD','parry','parryCD','hurt','invul','skillU','skillI','jumpBuffer'])p[k]=Math.max(0,p[k]-dt);if(p.ground){p.coyote=.12;p.jumps=0;}else p.coyote=Math.max(0,p.coyote-dt);if(tap('jump'))p.jumpBuffer=.12;let direction=(down('right')?1:0)-(down('left')?1:0);if(direction)p.face=direction;
if(p.rope){p.vx=0;p.vy=0;p.y=clamp(p.y+((down('down')?1:0)-(down('up')?1:0))*230*dt,p.rope.y+40,p.rope.bottom);p.x=p.rope.x;if(tap('jump')||direction){p.rope=null;p.vy=-590;p.vx=direction*300;p.jumps=1;p.jumpBuffer=0;p.ropeCD=.35;}}else{p.ropeCD=Math.max(0,(p.ropeCD||0)-dt);if(down('up')&&!p.ropeCD){let rope=G.ropes.find(r=>Math.abs(r.x-p.x)<32&&p.y>r.y&&p.y-p.h<r.bottom);if(rope)p.rope=rope;}if(p.dash>0){p.dash-=dt;p.vx=p.face*770;p.vy=0;p.trail-=dt;if(p.trail<=0){p.trail=.035;G.ghosts.push({x:p.x,y:p.y,face:p.face,time:.22,walk:p.walk});}if(p.dash<=0&&has('dashlight')){particle(p.x,p.y-35,'#a9faff',25,300);for(let e of G.enemies)if(e.hp>0&&Math.abs(e.x-p.x)<155){e.stun=Math.max(e.stun,1);e.state='stun';}}}else if(p.hurt<=0){let speed=p.attack>0?140:320;p.vx=lerp(p.vx,direction*speed,Math.min(1,dt*(p.ground?16:9)));if(p.jumpBuffer>0&&(p.ground||p.coyote>0||p.jumps<2)){if(!p.ground&&p.coyote<=0)p.jumps=Math.max(p.jumps,1);p.jumps++;p.vy=p.jumps===1?-625:-570;p.ground=false;p.coyote=0;p.jumpBuffer=0;particle(p.x,p.y,'#bbd5d1',p.jumps===2?17:9,125,3,200);sfx('jump');}if(tap('dash')&&p.dashCD<=0){p.dash=.25;p.dashCD=.72;p.invul=.32;p.vy=0;particle(p.x,p.y-15,'#b5ded7',10,100);sfx('dash');}if(tap('parry')&&p.parryCD<=0){p.parry=.30+meta.upgrades.parry*.025;p.parryCD=.68;p.attack=0;tone(520,.08,'sine',.035);}
if(tap('attack')){if(p.attackCD>.03)p.queued=true;else doAttack();}if(p.queued&&p.attackCD<=0){p.queued=false;doAttack();}if(tap('skillU'))useSkill('U');if(tap('skillI'))useSkill('I');if(tap('ult'))ultimate();}else p.vx*=Math.pow(.08,dt);physics(p,dt);}
p.walk+=Math.abs(p.vx)*dt*.035;if(p.ground&&Math.abs(p.vx)>170&&Math.random()<.25)particle(p.x,p.y,'#9cafa866',1,35,2,20);if(p.y>850){p.x=150;p.y=500;p.vy=0;if(G.mode==='play')hurtPlayer(12,null);}if(tap('interact'))interact();}
const TAUNTS=['네 칼은 버터도 못 자르겠어!','도망도 기술이라더라!','그 얼굴로 해적을 한다고?','네 허풍에 배가 뜨겠구나!'];
function beginWindup(e){e.state='windup';e.windup=e.type==='boss'?(e.phase===2?.62:.85):e.type==='crab'?.56:.76;e.timer=e.windup;e.face=G.p.x>e.x?1:-1;e.taunt=e.type==='crab'?'딱! 딱! (겁났게?)':pick(TAUNTS);e.tauntTime=e.windup+1;e.hit=false;e.pattern=e.type==='boss'?(e.pattern+1)%3:0;}
function updateEnemy(e,dt){if(e.hp<=0){e.dead=Math.max(0,e.dead-dt);return;}e.hurt=Math.max(0,e.hurt-dt);e.tauntTime=Math.max(0,e.tauntTime-dt);if(e.poison>0){e.poison-=dt;e.poisonTick-=dt;if(e.poisonTick<=0){e.poisonTick=1;let damage=has('stunparry')&&e.stun>0?15:5;e.hp-=damage;particle(e.x,e.y-35,'#9bc579',4,50,3);textAt(damage,e.x,e.y-80,'#b7de8b',14);if(e.hp<=0){killEnemy(e);return;}}}if(e.type==='boss'&&e.hp<e.maxHp*.5&&e.phase===1){e.phase=2;e.taunt='좋아, 이제 진짜 선장처럼 굴어 주지!';e.tauntTime=3;shake(8);particle(e.x,e.y-50,'#eeb878',30,250);}
if(e.stun>0){e.stun-=dt;e.state='stun';e.vx*=Math.pow(.03,dt);if(e.stun<=0){e.state='idle';e.cooldown=.12;}physics(e,dt);return;}
let dx=G.p.x-e.x,dy=Math.abs(G.p.y-e.y),dist=Math.abs(dx);if(e.state==='windup'){e.timer-=dt;e.vx*=Math.pow(.001,dt);if(e.timer<=0){e.state='attack';e.attack=e.type==='boss'&&e.pattern===1?.55:.23;e.vx=e.face*(e.type==='crab'?430:e.type==='boss'&&e.pattern===1?610:180);G.slashes.push({x:e.x+e.face*45,y:e.y-e.h*.5,face:e.face,combo:e.type==='boss'?2:0,time:.28,max:.28,enemy:true});if(e.type==='boss'&&e.pattern===2){for(let side of [-1,1])G.projectiles.push({x:e.x+side*60,y:620,vx:side*370,vy:0,type:'wave',time:2,owner:'enemy',source:e});shake(7);}if(e.type==='rope'){G.projectiles.push({x:e.x,y:e.y-55,vx:e.face*410,vy:-40,type:'hook',time:2.5,owner:'enemy',source:e});e.hit=true;}sfx('slash');}}else if(e.state==='attack'){e.attack-=dt;let reach=e.type==='boss'?(e.pattern===2?190:145):e.type==='crab'?65:100;if(!e.hit&&dist<reach&&dy<100&&(dx*e.face>-20)){e.hit=true;hurtPlayer(e.damage+(e.type==='boss'&&e.phase===2?3:0),e);}if(e.attack<=0){e.state='idle';e.cooldown=e.type==='boss'?(e.phase===2?.75:1.1):rand(1.05,1.8);e.vx=0;}}else{e.cooldown-=dt;e.face=dx>0?1:-1;let range=e.type==='rope'?420:e.type==='boss'?185:90;if(dist<range&&dy<100&&e.cooldown<=0)beginWindup(e);else if(dist>range*.8&&dist<900){e.vx=e.face*e.speed;if(e.ground&&G.p.y<e.y-90&&dist<420){e.vy=-590;}if(e.ground&&G.p.y>e.y+80){e.y+=12;}}else e.vx*=Math.pow(.01,dt);}
e.walk+=Math.abs(e.vx)*dt*.03;physics(e,dt);}
function explode(p){particle(p.x,p.y,'#f9c67a',42,410,5);G.slashes.push({x:p.x,y:p.y,time:.45,max:.45,blast:true});shake(9);sfx('bomb');for(let e of G.enemies)if(e.hp>0&&Math.hypot(e.x-p.x,e.y-e.h*.5-p.y)<210){damageEnemy(e,40,400);e.stun=Math.max(e.stun,.8);}}
function updateProjectiles(dt){for(let p of G.projectiles){p.time-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.type==='bomb'){p.vy+=880*dt;if(p.time<=0||p.y>=635){explode(p);p.remove=true;}}else{let hero=G.p;if(Math.abs(p.x-hero.x)<35&&Math.abs(p.y-(hero.y-40))<48){hurtPlayer(12,p.source);p.remove=true;}if(p.time<=0||p.x<0||p.x>G.world)p.remove=true;}}G.projectiles=G.projectiles.filter(p=>!p.remove);}
function updateDrops(dt){for(let d of G.drops){d.t+=dt;d.vy+=800*dt;d.x+=d.vx*dt;d.y+=d.vy*dt;if(d.y>638){d.y=638;d.vy=-Math.abs(d.vy)*.35;d.vx*=.7;}let dx=G.p.x-d.x,dy=G.p.y-35-d.y;if(d.t>.3&&Math.hypot(dx,dy)<210){d.x+=dx*dt*9;d.y+=dy*dt*9;if(Math.hypot(dx,dy)<35){d.remove=true;G.run.gold+=3;sfx('coin');particle(d.x,d.y,'#f9cd76',3,60,2);}}if(d.t>15){G.run.gold+=3;d.remove=true;}}G.drops=G.drops.filter(d=>!d.remove);}
function updateEffects(dt){for(let p of G.particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.g*dt;p.vx*=1-dt*.8;}G.particles=G.particles.filter(p=>p.life>0);for(let f of G.texts){f.time-=dt;f.y+=f.vy*dt;}G.texts=G.texts.filter(f=>f.time>0);for(let s of G.slashes)s.time-=dt;G.slashes=G.slashes.filter(s=>s.time>0);for(let gh of G.ghosts)gh.time-=dt;G.ghosts=G.ghosts.filter(gh=>gh.time>0);G.shake=Math.max(0,G.shake-dt*30);G.flash=Math.max(0,G.flash-dt*2);if(G.banner){G.banner.time-=dt;if(G.banner.time<=0)G.banner=null;}if(G.toastTime>0){G.toastTime-=dt;if(G.toastTime<=0)$('#toast').classList.remove('visible');}}
function menuPad(){if(inputDevice!=='gamepad'||!$('#overlay').classList.contains('open'))return;const items=[...$('#overlay').querySelectorAll('button:not(:disabled)')];if(!items.length)return;let index=items.indexOf(document.activeElement);if(tap('left')||tap('up'))items[(index-1+items.length)%items.length].focus();if(tap('right')||tap('down'))items[(index+1)%items.length].focus();if(tap('jump'))(items[index]||items[0]).click();}
function update(dt){G.t+=dt;pollPad();if(tap('pause')){if(G.mode==='paused'||G.mode==='dialog')resume();else if(['hub','play'].includes(G.mode))pause();}if(!['play','hub'].includes(G.mode)){menuPad();}if(!['hub','play','title'].includes(G.mode)){pressed.clear();return;}music(dt);updateEffects(dt);if(G.mode==='title'){pressed.clear();return;}if(G.hitstop>0){G.hitstop-=dt;pressed.clear();return;}if(G.run)G.run.time+=dt;updatePlayer(dt);if(G.mode==='play'){for(let e of G.enemies)updateEnemy(e,dt);updateProjectiles(dt);updateDrops(dt);if(!G.cleared&&G.enemies.length&&G.enemies.every(e=>e.hp<=0)){G.cleared=true;G.clearTimer=.9;G.banner={title:G.room===3?'갈고리도 말발 앞엔 무뎌진다.':'되찾은 밤, 하나의 미소.',sub:'ROOM CLEAR · 다음 문을 선택하세요',time:2.3};if(G.room===1&&!meta.clues.includes('tooth')){meta.clues.push('tooth');save();toast('단서 획득 · 금니에 새겨진 D.P.');}}if(G.cleared&&G.clearTimer>0){G.clearTimer-=dt;if(G.clearTimer<=0&&G.room===7){victory();}}}G.camera=lerp(G.camera,clamp(G.p.x-W*.39,0,G.world-W),Math.min(1,dt*5));updatePrompt();updateHUD();pressed.clear();}
function updatePrompt(){let near=G.npcs.find(n=>Math.abs(n.x-G.p.x)<100&&Math.abs(n.y-G.p.y)<100);let door=G.doors.find(d=>Math.abs(d.x-G.p.x)<80&&Math.abs(d.y-G.p.y)<100);let text='';if(near)text=`${inputDevice==='gamepad'?'LB':'E'} · ${near.name}와 대화`;else if(door){if(G.mode==='hub'||G.cleared)text=`${inputDevice==='gamepad'?'LB':'E'} · ${door.label||rewardName(door.type)}`;else text='적을 모두 물리치면 문이 열립니다.';}else if(G.p.rope)text='↑ ↓ 밧줄 오르기 · Space 뛰어내리기';else if(G.ropes.some(r=>Math.abs(r.x-G.p.x)<35&&G.p.y>r.y&&G.p.y-G.p.h<r.bottom))text='↑ 밧줄 잡기';G.prompt=text;$('#prompt').textContent=text;$('#prompt').style.display=text?'block':'none';}
function rewardName(t){return ({smile:'주민의 미소',gold:'금화 주머니',heal:'따뜻한 럼차',weapon:'무기 보관함',boss:'깡패 선장의 갑판',depart:'달빛 부두로 출항'})[t]||t;}
function interact(){let n=G.npcs.find(n=>Math.abs(n.x-G.p.x)<100&&Math.abs(n.y-G.p.y)<100);if(n){npcTalk(n.type);return;}let d=G.doors.find(d=>Math.abs(d.x-G.p.x)<85&&Math.abs(d.y-G.p.y)<100);if(!d||!(G.mode==='hub'||G.cleared))return;if(d.type==='depart'){newRun();return;}if(d.type==='boss'){loadRoom(7);return;}G.run.reward=d.type;if(d.type==='smile')chooseBoon();else if(d.type==='weapon')weaponReward();else if(d.type==='gold'){G.run.gold+=45;toast('금화 45 획득');loadRoom(G.room+1);}else if(d.type==='heal'){let n=30+meta.upgrades.flask*5;G.run.hp=Math.min(G.run.maxHp,G.run.hp+n);loadRoom(G.room+1);toast('따뜻한 럼차 · 체면 '+n+' 회복');}}
function updateHUD(){let r=G.run;$('#depart-shortcut').hidden=!!r;let hp=r?r.hp:100+meta.upgrades.health*12,max=r?r.maxHp:hp;$('#health-fill').style.width=hp/max*100+'%';$('#health-text').textContent=`${Math.ceil(hp)} / ${max}`;$('#laugh-fill').style.width=(r?r.laugh:0)+'%';$('#laugh-text').textContent=(r?Math.floor(r.laugh):0)+'%';$('#area-label').textContent=G.mode==='hub'?'밤의 갈매기 · 출항 준비':G.room===7?'브락의 갑판':G.room===6?'떠돌이의 정박지':'달빛 부두 · '+ROOM_NAMES[G.layout];$('#room-objective').textContent=r?(G.cleared?'문을 골라 다음 방으로 →':'남은 적 '+G.enemies.filter(e=>e.hp>0).length):'주민과 대화하거나 출항하세요';$('#room-dots').textContent=r?Array.from({length:8},(_,i)=>i<G.room?'◆':i===G.room?'◇':'·').join(' '):'HOME · MOONLIT HARBOR';$('#currency').textContent=r?'◈ '+r.gold:'금니 '+meta.teeth+' · 필름 '+meta.film;$('#weapon-name').textContent=r&&r.weapon==='flail'?'고무 닭 플레일':'녹슨 커틀러스';$('#boon-count').textContent=r?'되찾은 미소 '+r.boons.length:'E · 주민과 대화하기';for(let [id,v] of [['chicken',G.p?.skillU||0],['bomb',G.p?.skillI||0]]){let el=$('#skill-'+id);el.classList.toggle('cooldown',v>0);el.querySelector('b').textContent=v>0?v.toFixed(1)+'초':'준비';}$('#skill-ult b').textContent=r&&r.laugh>=100?'준비 완료':(r?Math.floor(r.laugh):0)+'%';$('#skill-ult').classList.toggle('ready',r&&r.laugh>=100);$('#boss-hud').hidden=!(G.boss&&G.boss.hp>0);if(G.boss){$('#boss-fill').style.width=Math.max(0,G.boss.hp/G.boss.maxHp*100)+'%';$('#boss-name').textContent=G.boss.phase===2?'브락 · 허풍이 벗겨진 선장':'깡패 선장 브락';}}
// Drawing helpers and a small two-bone animation rig. World coordinates stay in CSS-independent units.
function poly(points,fill,stroke=null,width=2){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
function line(points,color,width=2){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();}
function ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();}
function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function label(text,x,y,size=14,color='#e9dfc4',align='center'){ctx.font=`600 ${size}px ${FONT}`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(text,x,y);}
function glow(x,y,r,color){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);}
function lantern(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);let f=.8+Math.sin(G.t*5+x)*.08;glow(0,0,95,`rgba(248,173,83,${.17*f})`);line([[0,-38],[0,-20]],'#1b2834',3);poly([[-11,-18],[11,-18],[14,17],[-14,17]],'#16232d','#071220',3);ctx.fillStyle='#f2c277';ctx.fillRect(-8,-14,16,27);line([[0,-15],[0,14]],'#364044',2);ellipse(0,1,4,8,'#ffecba');poly([[-17,-19],[0,-29],[17,-19]],'#24323b','#0b192a',2);poly([[-17,17],[17,17],[10,23],[-10,23]],'#162330');ctx.restore();}
function barrel(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);poly([[-24,0],[-28,-15],[-28,-50],[-21,-65],[21,-65],[28,-50],[28,-15],[24,0]],'#5a4540','#101c2b',3);for(let i=-16;i<=16;i+=11)line([[i,0],[i*1.12,-32],[i,-63]],'#7f6050',2);roundRect(-28,-49,56,7,1,'#28383e');roundRect(-28,-16,56,7,1,'#28383e');ellipse(0,-64,21,5,'#826048');ctx.restore();}
