function drawHeroSprite(p,ghost=false){let flail=G.run?.weapon==='flail'&&FLAIL.naturalWidth,image=flail?FLAIL:HERO;if(!image.complete||!image.naturalWidth)return false;let frame=4;let moving=Math.abs(p.vx||0)>55&&p.ground;if(moving)frame=Math.floor(p.walk*1.1)%4;if(!p.ground)frame=p.vy<0?5:6;if(p.attack>0)frame=7+p.combo;if(p.parry>0)frame=10;if(p.dash>0)frame=11;if(p.rope)frame=5;const boxes=ASSETS.frames?.[flail?'hero-flail-atlas':'hero-atlas'];if(!boxes)return false;let b=boxes[frame],pivot=[193,530,925,1258,185,548,900,1200,215,555,950,1270][frame],scale=flail?.338:.35;ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.face||1,1);if(p.hurt>0&&!ghost)ctx.globalAlpha=.6+Math.sin(G.t*70)*.3;if(p.dash>0){ctx.translate(0,-32);ctx.rotate((.25-p.dash)*Math.PI*5);ctx.translate(0,32);}let bob=moving?Math.sin(p.walk*2)*1.5:Math.sin(G.t*2.8)*.7;ctx.drawImage(image,b[0],b[1],b[2]-b[0],b[3]-b[1],(b[0]-pivot)*scale,-(b[3]-b[1])*scale+bob,(b[2]-b[0])*scale,(b[3]-b[1])*scale);ctx.restore();return true;}

