function drawEnemySprite(e){if(!ENEMIES.complete||!ENEMIES.naturalWidth||!ASSETS.frames)return false;const boss=e.type==='boss'||e.type==='elite';let frame=0;if(Math.abs(e.vx)>15)frame=Math.floor(e.walk*.8)%2;if(e.state==='windup')frame=2;if(e.state==='attack')frame=3;let index=frame+(boss?4:0),b=ASSETS.frames['enemies-atlas'][index],pivot=[230,655,1060,1455,225,625,1090,1475][index],scale=e.type==='boss'?.40:e.type==='elite'?.33:.32;ctx.save();ctx.translate(e.x,e.y);ctx.scale(e.face,1);if(e.dead>0){ctx.globalAlpha=e.dead/.65;ctx.rotate(-1.3*(1-e.dead/.65));}if(e.hurt>0)ctx.globalAlpha=.75;let bob=Math.abs(e.vx)>15?Math.sin(e.walk*2)*2:Math.sin(G.t*2.5+e.id)*1.3;if(e.state==='windup')ctx.translate(-Math.sin((1-e.timer/e.windup)*Math.PI)*5,0);ctx.drawImage(ENEMIES,b[0],b[1],b[2]-b[0],b[3]-b[1],(b[0]-pivot)*scale,-(b[3]-b[1])*scale+bob,(b[2]-b[0])*scale,(b[3]-b[1])*scale);if(e.type==='rope')line([[22,-65],[35,-64],[39,-52],[32,-45],[24,-50]],'#c5d4d3',4);ctx.restore();return true;}

function drawCrab(e){ctx.save();ctx.translate(e.x,e.y);ctx.scale(e.face,1);if(e.dead>0)ctx.globalAlpha=e.dead/.65;let t=e.walk;for(let side of [-1,1])for(let i=0;i<3;i++){let x=side*(14+i*3);line([[x,-12],[side*(30+i*2),-13+Math.sin(t+i)*4],[side*(36+i*2),-2]],'#142b39',6);line([[x,-12],[side*(30+i*2),-13+Math.sin(t+i)*4],[side*(36+i*2),-2]],'#b28663',3);}ellipse(0,-22,28,17,e.hurt>0?'#e0b28b':'#ae7357');poly([[-21,-31],[-9,-40],[17,-36],[27,-24],[7,-26]],'#d6996b');for(let x of [-10,10]){line([[x,-29],[x*1.2,-42]],'#a7815d',4);ellipse(x*1.2,-42,5,5,'#e4d8b0');ellipse(x*1.2+1,-42,2,3,'#0c1c29');}let raise=e.state==='windup'?20:0;line([[19,-21],[38,-27-raise]],'#bb8d62',7);poly([[34,-33-raise],[47,-42-raise],[46,-29-raise],[55,-37-raise],[53,-21-raise],[35,-20-raise]],'#d6a37b','#394044',2);ctx.restore();}
function drawEntity(e,hero=false){if(!hero&&e.hp<=0&&e.dead<=0)return;let gy=e.y;ellipse(e.x,gy+1,e.type==='boss'?52:27,7,'#030c1680');if(hero){if(e.invul>0&&Math.floor(G.t*18)%2===0)ctx.globalAlpha=.6;if(!drawHeroSprite(e))drawRig(e,true);ctx.globalAlpha=1;if(e.parry>0){ctx.save();ctx.translate(e.x+e.face*16,e.y-48);ctx.strokeStyle='#b6f7e6';ctx.shadowColor='#70e7df';ctx.shadowBlur=14;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,53,-1.35+(e.face===-1?Math.PI:0),1.35+(e.face===-1?Math.PI:0));ctx.stroke();ctx.restore();}}else if(e.type==='crab')drawCrab(e);else if(!drawEnemySprite(e))drawRig(e);
if(!hero&&e.hp>0){if(e.hp<e.maxHp&&e.type!=='boss'){roundRect(e.x-26,e.y-e.h-39,52,4,2,'#0a1628');roundRect(e.x-26,e.y-e.h-39,52*e.hp/e.maxHp,4,2,e.type==='elite'?'#e7bd75':'#deaaa0');}if(e.state==='windup'){let ready=e.timer<=.3+meta.upgrades.parry*.025;let color=ready?'#ffdc81':'#b48ad7';glow(e.x,e.y-e.h-30,ready?58:28,ready?'#ffbd6745':'#b07cdc20');label(ready?'✦':'!',e.x,e.y-e.h-37,ready?36:24,color);if(e.type==='boss'&&meta.bossKnown){label('받아치기!',e.x,e.y-e.h-78,15,'#aaf3e6');}}if(e.stun>0){for(let i=0;i<3;i++){let a=G.t*4+i*2.1;label('✧',e.x+Math.cos(a)*21,e.y-e.h-18+Math.sin(a)*5,14,'#dfd78d');}}if(e.tauntTime>0&&e.type!=='boss'){ctx.font=`11px ${FONT}`;let width=Math.min(240,ctx.measureText(e.taunt).width+24);roundRect(e.x-width/2,e.y-e.h-92,width,28,5,'#0c1c2be8','#d3b68066');label(e.taunt,e.x,e.y-e.h-78,11,'#e5cfab');}if(e.type==='boss'&&e.tauntTime>0){label(e.taunt,e.x,e.y-e.h-83,18,'#e7cfb7');}}}
function drawSlash(s){ctx.save();ctx.translate(s.x,s.y);ctx.globalAlpha=clamp(s.time/s.max,0,1);if(s.blast){let r=210*(1-s.time/s.max);glow(0,0,Math.max(10,r),'#ffa74490');ctx.strokeStyle='#fbd8a1';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke();}else if(s.chicken){let t=1-s.time/s.max;ctx.rotate(t*Math.PI*4);ctx.strokeStyle='#f4ca72';ctx.lineWidth=4;ctx.setLineDash([9,12]);ctx.beginPath();ctx.arc(0,0,140*t+25,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);label('꽥!',70,0,30,'#ffe9af');}else{ctx.scale(s.face||1,1);let t=1-s.time/s.max;ctx.rotate(s.combo===1?-1.1:.15);ctx.lineWidth=s.parry?18:s.combo===2?15:9;ctx.strokeStyle=s.enemy?'#f1a78c':s.parry?'#b9fff1':s.flail?'#f9d580':'#d6f8e6';ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=16;ctx.beginPath();ctx.ellipse(-22,0,s.combo===2?133:105,63,0,-1.5+t*.5,1.3-t*.4);ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#ffffff';ctx.beginPath();ctx.ellipse(-19,0,s.combo===2?144:116,70,0,-1.35,1.15);ctx.stroke();}ctx.restore();}
function render(){ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,W,H);drawBackdrop();if(G.mode==='title'){drawAmbient();return;}ctx.save();let sx=G.shake?rand(-G.shake,G.shake):0,sy=G.shake?rand(-G.shake*.5,G.shake*.5):0;ctx.translate(-G.camera+sx,sy);drawEnvironment();for(let gh of G.ghosts){ctx.globalAlpha=gh.time/.22*.25;if(!drawHeroSprite({...gh,dash:.15},true))drawRig({...gh,dash:.15},true,true);}ctx.globalAlpha=1;for(let d of G.drops){glow(d.x,d.y,17,'#ffcc6633');ellipse(d.x,d.y,5,6,'#ebc276');ellipse(d.x-1,d.y-1,2,3,'#ffedb0');}for(let e of G.enemies)drawEntity(e);drawEntity(G.p,true);for(let p of G.projectiles){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(G.t*10);if(p.type==='bomb'){ellipse(0,0,13,16,'#5d5143');line([[-10,-3],[10,-3]],'#a78650',3);line([[0,-16],[4,-23]],'#cba765',2);glow(4,-23,15,'#ffd68977');ellipse(4,-23,3,3,'#ffe0a3');}else if(p.type==='wave'){ctx.rotate(-G.t*10);glow(0,0,35,'#ec946b44');line([[-14,15],[0,-30],[12,10]],'#f4bd89',5);}else{line([[-15,0],[10,0],[16,9],[9,16],[0,12]],'#bcc9c9',4);}ctx.restore();}for(let s of G.slashes)drawSlash(s);for(let p of G.particles){ctx.globalAlpha=clamp(p.life/.3,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x-p.size/2,p.y-p.size/2,p.size,p.size);}ctx.globalAlpha=1;for(let f of G.texts){ctx.globalAlpha=clamp(f.time/.3,0,1);ctx.strokeStyle='#0b1d2e';ctx.lineWidth=4;ctx.font=`800 ${f.size}px ${FONT}`;ctx.textAlign='center';ctx.strokeText(f.text,f.x,f.y);ctx.fillStyle=f.color;ctx.fillText(f.text,f.x,f.y);}ctx.globalAlpha=1;ctx.restore();
// Foreground framing travels faster than the camera, emphasizing movement.
ctx.save();ctx.translate(-G.camera*1.18,0);for(let i=0;i<8;i++){let x=i*580-50;line([[x,820],[x+8,706]],'#071320',24);line([[x+8,723],[x+165,760],[x+335,727]],'#0a1827',6);}ctx.restore();if(G.mode==='play'&&!G.cleared){let left=G.enemies.filter(e=>e.hp>0&&e.x<G.camera-20).length,right=G.enemies.filter(e=>e.hp>0&&e.x>G.camera+W+20).length;if(left)label('← 적 '+left,55,420,13,'#e9c18d');if(right)label('적 '+right+' →',W-55,420,13,'#e9c18d');}const vignette=ctx.createRadialGradient(W/2,H/2,250,W/2,H/2,850);vignette.addColorStop(0,'transparent');vignette.addColorStop(1,'#030c185e');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);drawAmbient();if(G.flash>0&&!meta.reduced){ctx.fillStyle=`rgba(205,235,235,${G.flash*.4})`;ctx.fillRect(0,0,W,H);}if(G.banner){let opacity=Math.min(1,G.banner.time,3-G.banner.time+.1);ctx.globalAlpha=Math.max(.05,opacity);let y=235;let grad=ctx.createLinearGradient(W/2-450,0,W/2+450,0);grad.addColorStop(0,'#07142500');grad.addColorStop(.3,'#071425cb');grad.addColorStop(.7,'#071425cb');grad.addColorStop(1,'#07142500');ctx.fillStyle=grad;ctx.fillRect(W/2-450,y-46,900,103);label(G.banner.sub,W/2,y-20,12,'#d7b779');label(G.banner.title,W/2,y+16,G.banner.title.length>20?23:30,'#f2e2c5');ctx.globalAlpha=1;}}
function drawAmbient(){for(let i=0;i<30;i++){let x=(i*151+Math.sin(G.t*.3+i)*55-G.t*(i%3+1)*4)%W;if(x<0)x+=W;let y=(i*89+Math.cos(G.t*.5+i)*19)%H;let a=.1+Math.sin(G.t+i)*.08;ctx.fillStyle=`rgba(236,217,164,${a})`;ctx.beginPath();ctx.arc(x,y,1.2+i%2*.5,0,Math.PI*2);ctx.fill();}}
function btn(text,action,cls='',disabled=false){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;}
function openModal(content,cls=''){if(['play','hub'].includes(G.mode))G.backMode=G.mode;G.mode='dialog';keys.clear();pressed.clear();$('#overlay').className='open';$('#overlay').style.background='';$('#overlay').style.backdropFilter='';$('#overlay').innerHTML=`<section class="modal ${cls}" role="dialog" aria-modal="true">${content}</section>`;$('#overlay button')?.focus();}
function closeOverlay(){keys.clear();pressed.clear();$('#overlay').className='';$('#overlay').innerHTML='';G.mode=G.backMode||'hub';}
function title(){G.mode='title';G.worldMode='title';$('#hud').hidden=true;$('#overlay').className='open';$('#overlay').style.background='transparent';$('#overlay').style.backdropFilter='none';$('#overlay').innerHTML=`<section class="modal title-modal"><span class="eyebrow">A MOONLIT ACTION ROGUELITE</span><div class="title-small">The Secret of</div><div class="title-logo">DentPhoto<span>Village</span></div><p>달빛 아래, 칼끝보다 날카로운 한마디.<br>뛰어들고, 흘려내고, 받아쳐라.<br>사진사가 훔친 마을의 미소를 되찾는 밤이 시작된다.</p><div class="actions">${btn(meta.runs?'술집으로 돌아가기 →':'모험 시작 →','start','primary')}${btn('조작 방법','help')}${btn(meta.sound?'♫ 소리 켜짐':'♫ 소리 꺼짐','sound')}</div></section><div class="title-foot">CHAPTER 01 · THE MOONLIT HARBOR<br>키보드 / 게임패드 · ACTION EDITION<br>2026 · 아울러</div>`;$('#overlay button')?.focus();}
function endingPreview(){openModal(`${btn('×','resume','close-x')}<span class="eyebrow">CHAPTER 01 COMPLETE · THE LAST WORD</span><h1>“좋아. 네 말이 더 날카롭군.”</h1><p>브락은 모자를 벗고 한참을 웃었습니다.<br>“사진사에게 가려면 절벽 지붕길로 가. 그리고 이건… 내가 못 전한 초대장이야.”<br>닫혀 있던 항구의 등불이 하나둘 켜지고, 밤바다 위로 주민들의 미소가 번집니다.</p><div class="end-summary"><span>부두 지역 완료</span><span>처치 18</span><span>받아치기 7회</span><span>금니 +3</span></div><p class="hint">이 장면 뒤에는 절벽 마을과 저택의 사진사가 기다리고 있습니다.<br>실제 플레이에서는 8개 방을 돌파하고 선장 브락을 쓰러뜨리면 이 화면에 도착합니다.</p><div class="actions">${btn('처음 화면으로','title-return','primary')}${btn('실제 항해 시작','start')}</div>`);G.backMode='title';}
function help(){let wasTitle=G.mode==='title';openModal(`${btn('×','resume','close-x')}<span class="eyebrow">HOW TO PLAY</span><h1>한 박자 기다렸다가,<br>기막히게 받아치세요.</h1><div class="control-grid"><div><strong>움직이기 · ← → / A D</strong><p>Space로 2단 점프. 밧줄 곁에서 ↑를 누르면 잡고 오릅니다. 게임패드: 스틱 / A.</p></div><div><strong>3타 공격 · J</strong><p>연속으로 눌러 3타 콤보. 마지막 일격은 적을 밀어냅니다. 게임패드: X.</p></div><div><strong>구르기 · K</strong><p>짧은 무적 시간으로 적을 통과합니다. 위험하면 뒤로 물러나세요. 게임패드: B.</p></div><div><strong>받아치기 · L</strong><p>적 머리 위 금빛 ✦가 빛날 때! 약 0.3초 안의 공격을 반격합니다. 게임패드: RB.</p></div><div><strong>소품 · U / I</strong><p>고무 닭은 주변 공격과 기절, 럼 폭탄은 원거리 폭발. 게임패드: LT / RT.</p></div><div><strong>필살 대사 · O</strong><p>웃음 100%에서 광역 공격. 주민·문 곁에서 E로 상호작용. 게임패드: Y / LB.</p></div></div><p class="hint">Escape / Start: 일시정지 · Tab / Enter: 메뉴 선택<br>부두 8개 방 → 중간 강적 → 떠돌이 상인 → 선장 브락. 전투가 끝나면 문 위의 보상을 고르세요.<br>이 버전은 1지역 완성형 프로토타입입니다. 금니·필름·단서·강화는 자동 저장하며, 진행 중인 방과 빌드는 게임을 닫으면 초기화됩니다.</p><div class="actions">${btn('알겠어, 해 보자','resume','primary')}</div>`);if(wasTitle)G.backMode='title';}
function pause(){G.backMode=G.mode;openModal(`${btn('×','resume','close-x')}<span class="eyebrow">A MOMENT TO CATCH YOUR BREATH</span><h1>잠깐, 숨 돌리기.</h1><p>파도도 당신을 기다립니다.</p><div class="actions">${btn('계속하기 →','resume','primary')}${btn('조작 방법','help')}${btn('단서와 미소','journal')}${btn('전체 화면','fullscreen')}</div><div class="actions">${btn(meta.sound?'♫ 소리 켜짐':'♫ 소리 꺼짐','sound')}${btn(meta.reduced?'화면 흔들림 꺼짐':'화면 흔들림 켜짐','motion')}${btn('영구 기록 내보내기','export')}${btn('영구 기록 불러오기','import')}</div><p class="hint">영구 기록은 자동 저장됩니다. 현재 항해는 브라우저를 닫으면 종료됩니다.</p>${G.run?`<div class="actions">${btn('이번 항해를 마치고 술집으로','abandon')}</div>`:''}`);G.mode='paused';}
function resume(){if(G.offers?.length)return;let mode=G.backMode;closeOverlay();if(mode==='title'){title();return;}G.mode=mode||'hub';audioStart();}
function npcTalk(type){if(type==='rosa'){if(!meta.clues.includes('rumor')){meta.clues.push('rumor');save();}openModal(`${btn('×','resume','close-x')}<span class="eyebrow">밤의 갈매기 · 로사</span><h1>${meta.runs?'사진은 잘 나왔더라.':'칼이 서툴면, 말로 이기면 되지.'}</h1><p>${meta.runs?'“다음번엔 눈 좀 뜨고 찍혀. 현상액 값이 얼만데.”<br>로사는 따뜻한 수건을 건넸습니다. “넘어진 건 잊어. 네가 돌려준 미소는 아직 여기 있으니까.”':'“요즘 마을 사람들은 웃어도 이가 안 보인단다. 절벽 위 저택에서 플래시가 번쩍인 뒤부터야. 부두의 브락 선장이 뭔가를 알고 있을 거야.”'}</p><p class="hint">단서 획득 · 밤마다 사라지는 미소<br>받아치기와 3타 콤보로 관중 웃음을 모으세요. 맞으면 웃음이 조금 줄어듭니다.</p><div class="actions">${btn('좋아, 할 말은 준비됐어','resume','primary')}${btn('조작 방법','help')}</div>`);}else if(type==='lighthouse')upgradeMenu();else if(type==='smith')smithMenu();else merchantMenu();}
const UPGRADES=[['health','든든한 체면','시작 최대 체면 +12','♡'],['parry','한 박자 긴 여유','받아치기 판정 +0.025초','✦'],['flask','따뜻한 럼차','회복 보상 +5, 입장마다 체면 +2','♨'],['smile','소문난 말재주','출항 때 미소 선택. 추가 강화마다 선택지 +1 (최대 5장)','☼']];
function upgradeMenu(){openModal(`${btn('×','resume','close-x')}<span class="eyebrow">등대지기 노아 · 영구 강화</span><h1>불빛은, 꺼져도 다시 켜면 돼.</h1><p>금니 <strong style="color:var(--gold)">${meta.teeth}</strong>개 · “한밤중에도 배울 수 있는 게 있지.”</p><div class="stat-grid">${UPGRADES.map(([id,name,desc,icon])=>{let lv=meta.upgrades[id],cost=2+lv*2;return btn(`<strong>${icon} ${name} <small>${lv} / 5</small></strong><small>${desc}</small><span>${lv>=5?'최대 강화':cost+' 금니'}</span>`,'upgrade:'+id,'upgrade',lv>=5||meta.teeth<cost);}).join('')}</div><p class="hint">금니는 강적과 보스에게서 얻습니다. 강화는 다음 출항부터 적용됩니다.</p>`);}
function smithMenu(){openModal(`${btn('×','resume','close-x')}<span class="eyebrow">생선 장수 마리 · 무기 보관함</span><h1>칼보다 닭이 강할 때도 있지.</h1><p>보유 필름 ${meta.film} · 무기를 골라 다음 항해에 가져가세요.</p><div class="cards" style="grid-template-columns:1fr 1fr">${btn('<span class="icon">⚔</span><strong>녹슨 커틀러스</strong><p>빠른 3타 콤보. 받아치기 반격 피해 +8.</p><em>기본 무기 · 출항 무기로 선택</em>','equip:sword','boon-card')}${btn(`<span class="icon">♧</span><strong>고무 닭 플레일</strong><p>넓은 사거리, 묵직한 일격. 타격할 때 웃음이 더 빨리 찹니다.</p><em>${meta.flail?'해금 완료 · 출항 무기로 선택':'영구 해금 · 필름 5개'}</em>`,meta.flail?'equip:flail':'unlock','boon-card',!meta.flail&&meta.film<5)}</div><p class="hint">현재 선택: ${G.equipped==='flail'?'고무 닭 플레일':'녹슨 커틀러스'}. 방의 무기 보상에서는 아직 해금하지 않은 무기도 이번 항해에 사용할 수 있습니다.</p>`);}
function merchantMenu(){openModal(`${btn('×','resume','close-x')}<span class="eyebrow">떠돌이 상인 · 선장전 준비</span><h1>살아 돌아오면, 단골이지.</h1><p>보유 금화 ${G.run.gold} · 현재 체면 ${Math.ceil(G.run.hp)} / ${G.run.maxHp}</p><div class="stat-grid">${btn('<strong>♨ 따뜻한 럼차</strong><small>체면 40 회복</small><span>25 금화</span>','buyheal','upgrade',G.run.gold<25||G.run.hp>=G.run.maxHp)}${btn('<strong>☼ 되찾지 못한 미소</strong><small>미소 하나를 골라 힘을 얻습니다.</small><span>50 금화</span>','buysmile','upgrade',G.run.gold<50||G.run.boons.length>=9)}${btn('<strong>♧ 고무 닭 플레일</strong><small>이번 항해의 주무기를 교체합니다.</small><span>35 금화</span>','buyweapon','upgrade',G.run.gold<35||G.run.weapon==='flail')}${btn('<strong>♛ 선장을 만나러 간다</strong><small>거래를 마치고 출구로 걸어가세요.</small><span>행운은 무료</span>','resume','upgrade')}</div>`);}
function chooseBoon(context='next'){if(context===true)context='start';G.boonContext=context;let pool=BOONS.filter(b=>!G.run.boons.includes(b.id));if(!pool.length){G.run.hp=Math.min(G.run.maxHp,G.run.hp+25);if(context==='next')loadRoom(G.room+1);return;}G.offers=shuffle(pool).slice(0,context==='start'?Math.min(5,2+meta.upgrades.smile):3);openModal(`<span class="eyebrow">A SMILE SET FREE</span><h1>사진 속에서, 미소가 돌아왔다.</h1><p>주민 한 사람의 마음이 이번 항해에 힘을 보탭니다.</p><div class="cards" ${G.offers.length>3?'style="grid-template-columns:repeat('+G.offers.length+',1fr)"':''}>${G.offers.map(b=>btn(`<span class="icon">${b.icon}</span><small>${b.who}</small><strong>${b.name}</strong><p>${b.desc}</p><em>${b.quote}</em>`,'boon:'+b.id,'boon-card')).join('')}</div><p class="hint">등대지기의 ‘말문을 닫는 빛’ + 생선 장수의 ‘비린내 나는 칼끝’ = 기절한 적에게 독 피해 3배.</p>`);}
function takeBoon(id){if(!G.offers?.some(b=>b.id===id)||!G.run||G.run.boons.includes(id))return;G.run.boons.push(id);let b=BOONS.find(b=>b.id===id);if(!meta.residents.includes(b.who)){meta.residents.push(b.who);toast(b.who+'의 미소가 술집으로 돌아왔습니다.');}if(id==='heart'){G.run.maxHp+=20;G.run.hp+=20;}if(id==='radiance')addLaugh(25);save();let context=G.boonContext;G.offers=null;closeOverlay();if(context==='next')loadRoom(G.room+1);else if(context==='shop')merchantMenu();else{G.mode='play';updateHUD();}}
function weaponReward(){openModal(`<span class="eyebrow">A MOST UNUSUAL ARMORY</span><h1>뭘로 말문을 막을까요?</h1><div class="cards" style="grid-template-columns:1fr 1fr">${btn('<span class="icon">⚔</span><strong>녹슨 커틀러스</strong><p>빠른 콤보와 강한 받아치기 반격.</p>','weapon:sword','boon-card')}${btn('<span class="icon">♧</span><strong>고무 닭 플레일</strong><p>느리지만 넓은 공격. 맞힐 때마다 더 큰 웃음.</p>','weapon:flail','boon-card')}</div>`);}
function journal(){let wasTitle=G.mode==='title';openModal(`${btn('×','resume','close-x')}<span class="eyebrow">THE SMILE JOURNAL</span><h1>웃음의 행방</h1>${[['rumor','밤마다 사라지는 미소','로사가 들려준 소문. 저택의 플래시가 터진 뒤부터 주민들이 웃지 못한다.'],['tooth','금니에 새겨진 D.P.','부두에서 발견한 금니에는 사진사의 이니셜이 새겨져 있다. 오래된 선장의 유품일까?'],['captain','브락이 숨긴 초대장','브락이 지키던 초대장에는 “당신의 미소를 영원히”라는 문구가 적혀 있다.']].map(([id,title,text])=>`<div class="journal-row"><strong>${meta.clues.includes(id)?'✧ '+title:'○ 아직 찾지 못한 단서'}</strong><p>${meta.clues.includes(id)?text:'주민과 대화하고 부두를 돌파하면 발견할 수 있습니다.'}</p></div>`).join('')}<div class="journal-row"><strong>브락의 말버릇</strong><p>${meta.bossKnown?'“진짜 선장”이라는 말 이후 공격이 빨라진다. 다음 대결에서는 예고 표시가 더 눈에 띈다.':'브락에게 패배하면 말버릇을 기록합니다.'}</p></div>${G.run?`<h2 style="margin-top:22px">이번 밤의 미소</h2><p>${G.run.boons.map(id=>BOONS.find(b=>b.id===id).name).join(' · ')||'아직 돌아온 미소가 없습니다.'}</p>`:''}`);if(wasTitle)G.backMode='title';}
function die(){if(G.mode!=='play')return;let photo='';try{photo=canvas.toDataURL('image/jpeg',.65);}catch(e){}if(G.room===7){meta.bossKnown=true;}save();G.flash=1;G.backMode='hub';let r=G.run;openModal(`<span class="eyebrow">DEVELOPED, NOT DEFEATED</span><h1>이번 사진은…<br>조금 흔들렸네요.</h1>${photo?`<div class="death-photo"><img src="${photo}" alt="사진에 갇힌 마지막 순간"><span>현상 완료 · 눈은 뜨고 찍자.</span></div>`:''}<p>눈부신 플래시. 당신은 납작한 사진이 되었습니다.<br>로사는 사진을 현상액에 담그더니 말했습니다.<br>“또 왔니? 다음엔 웃으면서 찍혀.”</p><div class="end-summary"><span>금니 +${r.teethGained}</span><span>필름 +${r.filmGained}</span><span>받아치기 ${r.parries}회</span></div><p class="hint">금니·필름·단서·주민의 귀환은 남았습니다. 현재 미소와 금화는 사라집니다.${G.room===7?'<br>브락의 말버릇을 기록했습니다. 다음 대결에 예고가 표시됩니다.':''}</p><div class="actions">${btn('따뜻한 술집으로 돌아가기 →','hub','primary')}</div>`);G.mode='dead';}
function victory(){if(G.mode!=='play')return;meta.wins++;if(!meta.clues.includes('captain'))meta.clues.push('captain');meta.teeth+=3;G.run.teethGained+=3;save();let r=G.run;openModal(`<span class="eyebrow">CHAPTER 01 COMPLETE</span><h1>“좋아. 네 말이 더 날카롭군.”</h1><p>브락은 모자를 벗고 한참을 웃었습니다.<br>“사진사에게 가려면 절벽 지붕길로 가. 그리고 이건… 내가 못 전한 초대장이야.”<br>닫혀 있던 항구의 등불이 하나둘 켜졌습니다.</p><div class="end-summary"><span>${Math.floor(r.time/60)}분 ${Math.floor(r.time%60)}초</span><span>처치 ${r.kills}</span><span>받아치기 ${r.parries}</span><span>금니 +${r.teethGained}</span></div><p class="hint">부두 지역을 완료했습니다. 이 버전의 플레이 가능한 범위는 여기까지입니다.<br>절벽 마을과 사진사의 저택은 후속 지역입니다. 지금은 무기와 미소를 바꾸어 다시 항해할 수 있습니다.</p><div class="actions">${btn('미소가 돌아온 술집으로 →','hub','primary')}</div>`);G.mode='victory';}
function exportMeta(){let url=URL.createObjectURL(new Blob([JSON.stringify(meta,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='DentPhoto-Action-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function action(a){let [cmd,id]=a.split(':');if(cmd==='start'){audioStart();hub();return;}if(cmd==='hub'){hub();return;}if(cmd==='depart'&&G.mode==='hub'){newRun();return;}if(cmd==='resume'){resume();return;}if(cmd==='help'){help();return;}if(cmd==='pause'){if(['play','hub'].includes(G.mode))pause();return;}if(cmd==='journal'){journal();return;}if(cmd==='sound'){meta.sound=!meta.sound;save();audioStart();if(G.mode==='title')title();else{let old=G.backMode;G.mode=old;pause();}return;}if(cmd==='motion'){meta.reduced=!meta.reduced;save();let old=G.backMode;G.mode=old;pause();return;}if(cmd==='fullscreen'){document.fullscreenElement?document.exitFullscreen?.():document.documentElement.requestFullscreen?.().catch(()=>toast('전체 화면이 지원되지 않습니다.'));return;}if(cmd==='export'){exportMeta();return;}if(cmd==='import'){$('#import-file').click();return;}if(cmd==='abandon'){openModal('<h1>오늘 밤은 여기까지?</h1><p>금니와 필름, 단서는 남지만 이번 항해의 금화와 미소는 사라집니다.</p><div class="actions">'+btn('술집으로 돌아가기','hub','primary')+btn('계속 항해하기','resume')+'</div>');return;}if(cmd==='upgrade'&&UPGRADES.some(u=>u[0]===id)){let cost=2+meta.upgrades[id]*2;if(meta.teeth>=cost&&meta.upgrades[id]<5){meta.teeth-=cost;meta.upgrades[id]++;save();sfx('coin');upgradeMenu();}return;}if(cmd==='unlock'&&!meta.flail&&meta.film>=5){meta.film-=5;meta.flail=true;G.equipped='flail';save();smithMenu();return;}if(cmd==='equip'&&['sword','flail'].includes(id)&&(id==='sword'||meta.flail)){G.equipped=id;smithMenu();return;}if(cmd==='boon'){takeBoon(id);return;}if(!G.run)return;if(cmd==='weapon'&&['sword','flail'].includes(id)){G.run.weapon=id;closeOverlay();loadRoom(G.room+1);return;}if(cmd==='buyheal'&&G.run.gold>=25&&G.run.hp<G.run.maxHp){G.run.gold-=25;G.run.hp=Math.min(G.run.maxHp,G.run.hp+40);merchantMenu();return;}if(cmd==='buysmile'&&G.run.gold>=50&&G.run.boons.length<9){G.run.gold-=50;chooseBoon('shop');return;}if(cmd==='buyweapon'&&G.run.gold>=35){G.run.gold-=35;G.run.weapon='flail';merchantMenu();return;}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b&&!b.disabled){audioStart();action(b.dataset.action);}});
document.addEventListener('keydown',e=>{if(!$('#overlay').classList.contains('open'))return;if(e.key==='Tab'){let items=[...$('#overlay').querySelectorAll('button:not(:disabled)')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}}});
$('#import-file').addEventListener('change',async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>100000)throw Error();let d=JSON.parse(await f.text());if(!validMeta(d))throw Error();openModal(`<h1>이 영구 기록을 불러올까요?</h1><p>${d.runs}번 출항 · ${d.wins}번 부두 완료 · 금니 ${d.teeth} · 필름 ${d.film}<br>현재 항해는 끝나고 저장한 영구 기록으로 교체됩니다.</p><div class="actions"><button id="confirm-import" class="primary">기록 교체하기</button>${btn('취소','resume')}</div>`);$('#confirm-import').addEventListener('click',()=>{meta=d;save();hub();});}catch(e){toast('액션 버전의 올바른 저장 파일이 아닙니다.');}});
let last=0,acc=0;function frame(time){let dt=Math.min(.05,(time-last)/1000||1/60);last=time;acc+=dt;let steps=0;while(acc>=1/60&&steps<4){update(1/60);acc-=1/60;steps++;}render();requestAnimationFrame(frame);}
title();requestAnimationFrame(frame);
const actionOriginal=action; action=function(a){if(a==='ending-preview'){endingPreview();return;}if(a==='title-return'){title();return;}return actionOriginal(a);};
